import os


class CFG:
    """
    Configuration class for Idea 23: Heterogeneous Ensemble with SAM.
    """

    # =======================
    # General Settings
    # =======================
    seed = 42
    debug = False
    num_workers = 4
    device = "cuda"

    # =======================
    # Data Paths & Settings
    # =======================
    # Metadata files generated by the metadata script
    train_metadata_path = "./metadata/train.csv"
    val_metadata_path = "./metadata/val.csv"
    test_metadata_path = "./metadata/test.csv"

    # Directory for filtered spectrograms (overriding the metadata's default spectrogram path)
    # The idea explicitly requires using filtered spectrograms.
    filtered_spectrogram_dir = "./input/supplemental_data/filtered_spectrograms"

    # Number of folds for Iterative Stratified K-Fold
    n_folds = 5

    # =======================
    # Input Parameters
    # =======================
    # Dimensions: Frequency (H) x Time (W)
    # 1:2 aspect ratio as per idea description
    img_height = 224
    img_width = 448

    # Channels: 3 for Pseudo-RGB (ImageNet weights compatibility)
    in_channels = 3

    # =======================
    # Model Architecture
    # =======================
    # Heterogeneous ensemble backbones
    backbones = ["resnet18", "efficientnet_b0", "densenet121"]

    # Number of classes
    num_classes = 19

    # =======================
    # Training Hyperparameters
    # =======================
    batch_size = 32

    # Optimizer settings (AdamW)
    lr = 1e-3
    weight_decay = 1e-4

    # SAM (Sharpness-Aware Minimization) settings
    sam_rho = 0.05

    # Augmentation
    mixup_alpha = 0.4

    # Training duration
    # Target: ~1000 update steps per fold.
    # Approx 206 train samples / 32 batch_size ~= 6.5 steps/epoch.
    # 1000 steps / 6.5 ~= 153 epochs.
    epochs = 150

    # =======================
    # Inference
    # =======================
    # TTA: Original + 3 Time-Rolls (25%, 50%, 75%)
    tta_shifts = [0, 0.25, 0.50, 0.75]

    # =======================
    # Output
    # =======================
    output_dir = "./working/idea_23"
    submission_path = "./submission/submission.csv"

    @staticmethod
    def setup():
        """Ensure output directories exist."""
        os.makedirs(CFG.output_dir, exist_ok=True)
        os.makedirs(os.path.dirname(CFG.submission_path), exist_ok=True)


# Run setup immediately when module is imported to ensure directories exist
CFG.setup()
